using System;using System.Data;using System.Text;using System.Globalization;public partial class AdminGames:System.Web.UI.Page{public string ClubOptions="",GameOptions="",GamesTable="",st="";protected void Page_Load(object sender,EventArgs e){if(Session["userType"]==null||Session["userType"].ToString()!="Admin"){Response.Redirect("Home.aspx");return;}if(Page.IsPostBack){if(Request.Form["action"]=="הוסף משחק")AddGame();if(Request.Form["action"]=="עדכן תוצאה")UpdateResult();}LoadLists();}private void LoadLists(){DataTable c=MyAdoHelper.ExecuteDataTable("SELECT * FROM Clubs ORDER BY League,ClubName");StringBuilder co=new StringBuilder();for(int i=0;i<c.Rows.Count;i++)co.Append("<option value='"+c.Rows[i]["ClubId"]+"'>"+c.Rows[i]["ClubName"]+" - "+c.Rows[i]["League"]+"</option>");ClubOptions=co.ToString();DataTable g=MyAdoHelper.ExecuteDataTable("SELECT Games.GameId,Games.GameDate,Games.GameResult,A.ClubName ClubA,B.ClubName ClubB FROM Games INNER JOIN Clubs A ON Games.ClubAId=A.ClubId INNER JOIN Clubs B ON Games.ClubBId=B.ClubId ORDER BY GameDate DESC");StringBuilder go=new StringBuilder(),tab=new StringBuilder("<table class='dataTable'><tr><th>ID</th><th>משחק</th><th>תאריך</th><th>תוצאה</th></tr>");for(int i=0;i<g.Rows.Count;i++){go.Append("<option value='"+g.Rows[i]["GameId"]+"'>"+g.Rows[i]["ClubA"]+" נגד "+g.Rows[i]["ClubB"]+"</option>");tab.Append("<tr><td>"+g.Rows[i]["GameId"]+"</td><td>"+g.Rows[i]["ClubA"]+" נגד "+g.Rows[i]["ClubB"]+"</td><td>"+Convert.ToDateTime(g.Rows[i]["GameDate"]).ToString("dd/MM/yyyy HH:mm")+"</td><td>"+g.Rows[i]["GameResult"]+"</td></tr>");}tab.Append("</table>");GameOptions=go.ToString();GamesTable=tab.ToString();}private void AddGame(){int a,b;DateTime d;string league=MyAdoHelper.FixText(Request.Form["newLeague"]);if(!int.TryParse(Request.Form["clubA"],out a)||!int.TryParse(Request.Form["clubB"],out b)||a==b||!DateTime.TryParseExact(Request.Form["gameDate"],"dd/MM/yyyy HH:mm",CultureInfo.InvariantCulture,DateTimeStyles.None,out d)){st="נתוני המשחק אינם תקינים";return;}DataTable clubs=MyAdoHelper.ExecuteDataTable("SELECT * FROM Clubs WHERE ClubId IN("+a+","+b+") AND League=N'"+league+"'");if(clubs.Rows.Count!=2){st="שתי הקבוצות חייבות להשתייך לליגה שנבחרה";return;}MyAdoHelper.DoQuery("INSERT INTO Games(GameDate,League,ClubAId,ClubBId,GameResult) VALUES('"+d.ToString("yyyy-MM-dd HH:mm:ss")+"',N'"+league+"',"+a+","+b+",N'-1')");st="המשחק נוסף בהצלחה";}private void UpdateResult(){int gid,a,b;if(!int.TryParse(Request.Form["resultGame"],out gid)){st="יש לבחור משחק";return;}string r=MyAdoHelper.FixText(Request.Form["gameResult"]);string[] p=r.Split(':');if(p.Length!=2||!int.TryParse(p[0],out a)||!int.TryParse(p[1],out b)||a<0||b<0){st="התוצאה חייבת להיות בפורמט 2:3";return;}DataTable g=MyAdoHelper.ExecuteDataTable("SELECT * FROM Games WHERE GameId="+gid);if(g.Rows.Count==0){st="המשחק לא נמצא";return;}MyAdoHelper.DoQuery("UPDATE Games SET GameResult=N'"+r+"' WHERE GameId="+gid);if(a==b)MyAdoHelper.DoQuery("UPDATE Bets SET BetResult=0 WHERE GameId="+gid);else{int winner=Convert.ToInt32(g.Rows[0][a>b?"ClubAId":"ClubBId"]);MyAdoHelper.DoQuery("UPDATE Bets SET BetResult=CASE WHEN BetClubId="+winner+" THEN 1 ELSE 0 END WHERE GameId="+gid);}st="התוצאה וההימורים עודכנו בהצלחה";}}